import{_ as u,a0 as i,w as d,s as g,I as o,x as l,a1 as r,A as s,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Hugo 對比 Jekyll ：兩大領先的靜態頁面生成器之間的比較 | LCTT x X-CMD","titleTemplate":false,"description":"Hugo 對比 Jekyll ：兩大領先的靜態頁面生成器之間的比較 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Hugo 對比 Jekyll ：兩大領先的靜態頁面生成器之間的比較 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Hugo 對比 Jekyll ：兩大領先的靜態頁面生成器之間的比較 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170518 Hugo vs. Jekyll Comparing the leading static website generators","title":"Hugo 對比 Jekyll ：兩大領先的靜態頁面生成器之間的比較","tag":"201706","desc":""},"relativePath":"201706/20170518 Hugo vs. Jekyll Comparing the leading static website generators.md","filePath":"[post].md"}'),p={name:"201706/20170518 Hugo vs. Jekyll Comparing the leading static website generators.md"};function a(k,e,m,y,f,H){const t=i("Link");return d(),g("div",null,[e[31]||(e[31]=o("h1",{id:"hugo-對比-jekyll-兩大領先的靜態頁面生成器之間的比較",tabindex:"-1"},[l("Hugo 對比 Jekyll ：兩大領先的靜態頁面生成器之間的比較 "),o("a",{class:"header-anchor",href:"#hugo-對比-jekyll-兩大領先的靜態頁面生成器之間的比較","aria-label":"Permalink to “Hugo 對比 Jekyll ：兩大領先的靜態頁面生成器之間的比較”"},"​")],-1)),e[32]||(e[32]=o("blockquote",null,[o("p",null,"如果你正在建一個新的網站，靜態頁面生成器或許是個正確的選擇。")],-1)),e[33]||(e[33]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/rh_003784_02_os.comcareers_os_rh2x.png?itok=4wXjYMBw",alt:"Hugo vs. Jekyll: Comparing the leading static website generators ",title:"Hugo vs. Jekyll: Comparing the leading static website generators "})],-1)),e[34]||(e[34]=o("p",null,"除非你是像艾米莉·狄金森那樣深居簡出的人，否則，當做了點事情後，你就會想要與這個世界分享。分享你的作品意味着需要一個網站。當然，你可以只是享受數字時代的便利，使用任何不同的社交網站來將你的作品呈現在觀眾面前。還有很多選擇，不僅僅是傳統的社交網站，例如 Artstation、Flickr、Soundcloud、Wattpad，不管你的媒介是什麼，總有一款屬於你的網站。",-1)),e[35]||(e[35]=o("p",null,"實際上，你_應該_使用這些網站，畢竟，人們都在這些網站上。然而，沒有一個地方是真正屬於你的。沒有一個網站是你能保證不管社交趨勢如何，人們都能在該網站上找到你的作品的。",-1)),e[36]||(e[36]=o("p",null,"控制權，這是擁有一個在網上屬於自己的地方的意義。",-1)),o("p",null,[e[1]||(e[1]=l("但是這篇文章不打算介紹註冊域名和託管你的網站。要介紹的是_後續_的步驟，真正地製作網頁。對於很多人來説，典型的選擇是使用像 ",-1)),r(t,{href:"http://wordpress.org/"},{default:s(()=>[...e[0]||(e[0]=[l("WordPress",-1)])]),_:1}),e[2]||(e[2]=l(" 那一類的軟件。在大多數主機託管商上，只需一次點擊即可安裝，然後就會有海量的插件和主題可供選擇。插件和主題的選擇取決於你想要製作的網頁的類型。但是 WordPress 不僅對於大部分網站來説有點過猶不及，還給了你一個有許多活動部件的動態頁面。如果你沒有保持這些部件最新，這些部件可能造成重大安全隱患，你的頁面因此被劫持。",-1))]),e[37]||(e[37]=o("p",null,"替代方法是擁有一個靜態網頁，在服務端沒有任何動態內容生成。只有一些原先的 HTML 和 CSS （或許還有點 Javascript 也挺好）。這種選擇的不好的一面是以後你要親自動手編寫所有的代碼。雖然可行，但你只是想要個地方來展示你的作品而已，你並不想知道底層網頁設計的特性（和重要的但卻令人頭疼的跨瀏覽器兼容性）。",-1)),o("p",null,[e[6]||(e[6]=l("使用靜態頁面生成器。你得到了靜態 HTML 頁面的速度與安全，但是是以有着接近於動態頁面的便利性的工作流程完成的。在靜態頁面生成器世界的兩大先驅是 ",-1)),r(t,{href:"http://gohugo.io/"},{default:s(()=>[...e[3]||(e[3]=[l("Hugo",-1)])]),_:1}),e[7]||(e[7]=l(" 和 ",-1)),r(t,{href:"https://jekyllrb.com/"},{default:s(()=>[...e[4]||(e[4]=[l("Jekyll",-1)])]),_:1}),e[8]||(e[8]=l(" ，（順道説下，Paolo Bonzini 的文章 《",-1)),r(t,{href:"https://opensource.com/article/17/4/getting-started-jekyll"},{default:s(()=>[...e[5]||(e[5]=[l("Jekyll 起步",-1)])]),_:1}),e[9]||(e[9]=l("》 寫得不錯）但是哪一個才是你的正確選擇？希望閲讀完這篇文章，你會更加了解。我們將基於易上手性、主題可用性、編輯方式和拓展性這幾點評估這兩個靜態頁面生成器。",-1))]),e[38]||(e[38]=n('<h3 id="開始" tabindex="-1">開始 <a class="header-anchor" href="#開始" aria-label="Permalink to “開始”">​</a></h3><p>公平地提醒一下，這兩個都需要你在命令列下使用他們。大部分命令都很直接和易於記憶，但是讓我們相應地調整下我們的期望吧，這不是點擊幾下鼠標就能做事的界面。</p><p>Jekyll 和 Hugo 的安裝都相當的簡單。 Jekyll 以 RubyGem 的方式安裝，Hugo 提供了一個方便的集成的二進制文件讓你迅速上手。因為安裝包單一，Hugo 以微弱優勢領先。雖然 Jekyll 的 RubyGems 安裝方式本身就很簡單，但是它_確實_需要你已經在你的電腦上正確安裝並且配置好 Ruby 環境。除了社區設計者和網頁開發者，大部分的使用者並沒有提前安裝好。</p><p>雖説是這樣，但是一旦安裝好，Hugo 和 Jekyll 都很好用。它們都有良好的文檔和快速開始指南。你用一個簡單命令新建一個頁面（在 Jekyll 裏是 <code>jekyll new &lt;your_site&gt;</code> ，在 Hugo 裏是 <code>hugo new site &lt;your_site&gt;</code>，譯者注：<code>&lt;your_site&gt;</code> 指代你網頁的名稱）。這一步新建了一個通用目錄結構和你網站的大致內容。目錄結構和基本的配置都十分相似。Jekyll 使用一個 <code>_config.yml</code> 文件，Hugo 使用 <code>config.toml</code>（雖然你_能_在 Hugo 的配置裏使用 YMAL 或者 JSON 語法，如果覺得其中一個使用起來更舒服的話）。每個內容文件的前置配置（front matter）元數據使用相同的配置語法。然後，所有的內容都是用 Markdown 寫的。</p><p>我想説就幫助你開始第一個靜態網頁這一點來説，Jekyll 稍微領先於 Hugo ，因為它能以一些基本的內容和一個默認主題開始着手使用。當在建設網頁時，你能使用這些內容作為一個樣板。Hugo 沒有樣例內容，甚至沒有一個默認主題。即便如此，樣例內容和默認主題是我在用任何工具建設網站時第一個刪除的內容，因此 Hugo 事實上幫我節省了這一步。</p><h3 id="主題" tabindex="-1">主題 <a class="header-anchor" href="#主題" aria-label="Permalink to “主題”">​</a></h3><p>正如我所提到的，Hugo 根本沒有默認主題，所以主題可能是你打算最先設置的。Jekyll 有一個得體的默認主題，雖然它只是個骨架。你或許也會想去為你的 Jekyll 頁面找一個主題。</p>',7)),o("p",null,[e[12]||(e[12]=l("Hugo 和 Jekyll 都有多種多樣的各類主題，網頁樣式從單頁面的主題到帶有Blog和評論的完善的多頁面主題都有，一應俱全。儘管如此，想找到滿足你需求的主題事實上並不簡單。無論使用哪個，主題網站——Hugo 的 ",-1)),r(t,{href:"https://themes.gohugo.io/"},{default:s(()=>[...e[10]||(e[10]=[l("themes.gohugo.io",-1)])]),_:1}),e[13]||(e[13]=l(" 和 Jekyll 的 ",-1)),r(t,{href:"http://jekyllthemes.org/"},{default:s(()=>[...e[11]||(e[11]=[l("jekyllthemes.org",-1)])]),_:1}),e[14]||(e[14]=l(" ，基本上都是一個充滿主題截圖的巨大頁面。一旦你點擊主題，你能得到關於該主題的一些十分詳細的信息，但是對於初步搜索相當困難。Hugo 的主題站有一些基本的標籤分類，但是大體上在我看來，主題搜索和展示都是這兩個項目需要繼續努力的。",-1))]),e[39]||(e[39]=n('<p>主題管理也是一個有趣的主題。在兩個項目中，幾乎每一個主題都是一個 Git 倉庫（經常是託管在 Github 上），你需要克隆（clone）下來到你的網頁建設地。在 Jekyll 裏，有額外的使用 RubyGems 的 bundle 的步驟來確保主題是由網站管理的。大部分主題都有一個 Gemfile，使得這一步驟輕鬆不少。如果主題沒有一個 Gemfile，添加也相當簡單。在 Hugo 裏沒有捆綁這一操作，只要在 <code>config.toml</code> 指向你的主題即可。</p><p>我發現我偏愛 Hugo 的主題處理。你可以克隆（clone）（或者新建）主題到 <code>themes</code> 裏它們自己的子文件夾裏。這不僅使得當你開始時能輕鬆地切換主題，而且也能讓你用自己的文件替換主題裏的任何組件。這意味着你能根據自己的品味自定義主題，而不用弄亂原始主題，使得這主題也可以通用於其他人。當然如果有一個你覺得其他用户會覺得值得的改變，你仍然可以編輯源文件，提交一個 PR（拉取請求，pull request）給主題維護者。</p><h3 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to “工作流程”">​</a></h3><p>一旦你設置好初始的配置，Jekyll 和 Hugo 的網站建設流程都很相似。兩者都有一個實時的 <code>serve</code> 命令，能在你的電腦上運行一個小型、輕量級的網頁服務器，所以你能在在本地測試你的網站而不用上傳到哪裏。很棒的是無論你是運行着 <code>jekyll serve</code> 還是 <code>hugo serve</code>，都默認配置為當你為之開發時，監視你對網站的任何修改。當你在瀏覽器裏看本地版的網站時，它會根據你的修改自動更新，不管你改的是內容、配置、主題、還僅僅是一張圖片。這確實很方便和節約時間。</p>',4)),o("p",null,[e[16]||(e[16]=l("在兩個系統中都是用 ",-1)),r(t,{href:"https://daringfireball.net/projects/markdown/"},{default:s(()=>[...e[15]||(e[15]=[l("Markdown",-1)])]),_:1}),e[17]||(e[17]=l(" 寫你的網站內容。如果碰巧你不熟悉 Markdown，（我來解釋下，）它是種很簡單的純文本編寫方式，還能有一些很好用的格式化符號。它很容易使用而且可閲讀。而且因為是純文本，你的內容（其實是你的網站）很容易進行版本控制。這是我最近寫幾乎所有東西的主要方式。",-1))]),e[40]||(e[40]=n('<p>新內容能通過在正確的地方手動創建文件添加到網站裏。新的文件只需要是有恰當的前置配置（front matter）元數據的 Markdown 文件即可。至於配置文件，Jekyll 對於前置配置使用 YAML 語法，Hugo 接受 TOML、YAML 或者 JSON（默認是 TOML）。新文件需要放置在正確的文件夾內，在 Jekyll 裏你需要把你編寫中的文件和已經完成了的內容頁分別放在 <code>_drafts</code> 和 <code>_posts</code> 目錄中。在 Hugo 中只有單獨一個 <code>content</code> 目錄。你可以根據文件的前置配置判斷這是否是一個草稿。</p><p>現在，雖然可以手動完成所有這些事情，但是 Hugo 提供了一些方便的功能確保你的新文件創建在正確的文件裏，那些文件也用恰當的前置配置預先配置好了。簡單地在終端中進入你網站的目錄，輸入 <code>hugo new content/&lt;page.md&gt;</code> ， <code>&lt;page.md&gt;</code> 代表着你想新建的新頁面。你甚至可以設置些包含為不同頁面自定義的前置配置、叫<strong>原型</strong>的模版（例如在你的網頁上同時有Blog和播客）。</p><p>當你的網頁弄好後，你能關閉你的預覽服務器，並用一個命令來建立你網站的真正頁面。在 Jekyll 裏是 <code>jekyll build</code>，Hugo 就僅僅是 <code>hugo</code>，Jekyll 把完成好的頁面放在 <code>_site</code> 的子目錄中。然而 Hugo 把這些文件放在名為 <code>public</code> 的子目錄中。不管哪種情況，一旦你完成後，你就有了一個完整的靜態網站，你能上傳並把它託管在幾乎任何地方。</p><h3 id="可拓展性" tabindex="-1">可拓展性 <a class="header-anchor" href="#可拓展性" aria-label="Permalink to “可拓展性”">​</a></h3><p>Hugo 和 Jekyll 都能讓你自定義你自己的網站上哪怕最小的一個點。然而就可拓展性而言，現在 Jekyll 因其插件 API 而遠遠領先。因為這種插件結構，很容易為你用 Jekyll 生成的網站添加功能，通過 Jekyll 社區或者你自己寫的相當短的代碼片段就能完成。</p><p>Hugo 現在根本沒有插件 API，所以添加功能有點難。希望以後支持編寫並包含插件。但是現在看不出有人在做這一點。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>大體上講，Hugo 和 Jekyll 十分相似。歸根結底由你工作體驗和你的網站需求決定。如果你已經設置好了 RubyGems 環境而且你需要插件的可拓展性，Jekyll 是你的選擇。然而，如果你看重一個簡單的工作流程，一個直接自定義網站的方式，那你首選 Hugo。</p><p>我發現我更喜歡 Hugo 的方法，而且在建設一個小型網站，我不需要任何插件。當然，每個人的需求都不同。你會為你的網站選擇哪一個靜態頁面生成器？</p><p>（題圖：opensource.com）</p><hr>',11)),o("p",null,[e[19]||(e[19]=l("via: ",-1)),r(t,{href:"https://opensource.com/article/17/5/hugo-vs-jekyll"},{default:s(()=>[...e[18]||(e[18]=[l("https://opensource.com/article/17/5/hugo-vs-jekyll",-1)])]),_:1})]),o("p",null,[e[23]||(e[23]=l("作者：",-1)),r(t,{href:"https://opensource.com/users/jason-van-gumster"},{default:s(()=>[...e[20]||(e[20]=[l("Jason van Gumster",-1)])]),_:1}),e[24]||(e[24]=l(" 譯者：",-1)),r(t,{href:"https://ypingcn.github.io/wiki/lctt"},{default:s(()=>[...e[21]||(e[21]=[l("ypingcn",-1)])]),_:1}),e[25]||(e[25]=l(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[22]||(e[22]=[l("wxy",-1)])]),_:1})]),o("p",null,[e[28]||(e[28]=l("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[26]||(e[26]=[l("LCTT",-1)])]),_:1}),e[29]||(e[29]=l(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:s(()=>[...e[27]||(e[27]=[l("Linux中國",-1)])]),_:1}),e[30]||(e[30]=l(" 榮譽推出",-1))])])}const C=u(p,[["render",a]]);export{b as __pageData,C as default};
